mapper.select:
SELECT id, doc_id, kb_id, chunk_index, content, heading_path, parent_title, start_page, end_page, token_count, collection_type, course_id, metadata_json, milvus_pk, parent_chunk_id, prev_chunk_id, next_chunk_id, char_offset_start, char_offset_end, correction_status, deleted, created_at, updated_at FROM document_chunk WHERE deleted = 0
AND doc_id = #{docId}
AND kb_id = #{kbId}
AND correction_status = 'PENDING'
AND doc_id IN (SELECT id FROM document WHERE deleted = 0 AND created_by = #{userId}) ORDER BY chunk_index

mapper.update:
UPDATE document_chunk SET next_chunk_id = CASE id
WHEN #{p.prevChunkId} THEN #{p.nextChunkId}
ELSE next_chunk_id END, prev_chunk_id = CASE id
WHEN #{p.nextChunkId} THEN #{p.prevChunkId}
ELSE prev_chunk_id END WHERE id IN #{p.prevChunkId}, #{p.nextChunkId}

UPDATE document_chunk SET dense_vector = CASE id
WHEN #{u.chunkId} THEN #{u.denseVector}
ELSE dense_vector END, milvus_pk = CASE id
WHEN #{u.chunkId} THEN #{u.milvusPk}
ELSE milvus_pk END WHERE id IN #{u.chunkId}
